    "route": "/index.html",
    "mimeType": "text/html; charset=utf-8",
    "body": "<!doctype html>\r\n<html lang=\"en\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<title>ScAInce Draw — mathematics and physics figures</title>\n<link rel=\"stylesheet\" href=\"styles.css\">\n<script>\nwindow.MathJax = {\n  startup: { typeset: false },\n  svg: {\n    fontCache: 'none'\n  }\n};\n</script>\n<script defer src=\"https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-svg.js\"></script>\n</head>\n<body>\n\r\n<header id=\"toolbar\" class=\"toolbar\"></header>\r\n\r\n<main class=\"layout\">\r\n\r\n  <aside class=\"pane pane-left\">\r\n    <h2>Shapes</h2>\r\n    <div id=\"palette\"></div>\r\n  </aside>\r\n\r\n  <div class=\"splitter\" data-side=\"left\" title=\"Drag to resize. Double click to collapse.\"></div>\r\n\r\n  <section class=\"pane pane-canvas\">\r\n    <div id=\"canvas-host\" class=\"canvas-host\" tabindex=\"0\"></div>\r\n    <div class=\"statusbar\">\r\n      <span id=\"status\" class=\"status\"></span>\r\n      <span class=\"spacer\"></span>\r\n      <button type=\"button\" id=\"help-button\" class=\"ghost tiny\" title=\"Keyboard and mouse reference\">\r\n        Shortcuts\r\n      </button>\r\n    </div>\r\n  </section>\r\n\r\n  <div class=\"splitter\" data-side=\"right\" title=\"Drag to resize. Double click to collapse.\"></div>\r\n\r\n  <aside class=\"pane pane-right\">\r\n    <h2>Properties</h2>\r\n    <div id=\"inspector\"></div>\r\n\r\n    <details class=\"section outline-section\" open>\r\n      <summary class=\"section-title\">Outline</summary>\r\n      <div id=\"outline\"></div>\r\n    </details>\r\n  </aside>\r\n\r\n</main>\r\n\r\n<dialog id=\"tikz-dialog\" class=\"tikz-dialog\">\r\n  <form method=\"dialog\">\r\n    <h2>TikZ source</h2>\r\n    <p class=\"muted small\">\r\n      Paste into a LaTeX document. The comment at the top lists every package\r\n      the figure needs.\r\n    </p>\r\n    <textarea id=\"tikz-output\" rows=\"20\" spellcheck=\"false\" readonly></textarea>\r\n    <div class=\"row gap\">\r\n      <button type=\"button\" id=\"tikz-copy\" class=\"primary\">Copy</button>\r\n      <button type=\"button\" id=\"tikz-download\">Download .tex</button>\r\n      <span class=\"spacer\"></span>\r\n      <button value=\"close\" class=\"ghost\">Close</button>\r\n    </div>\r\n  </form>\r\n</dialog>\r\n\r\n<dialog id=\"help-dialog\" class=\"help-dialog\">\r\n  <form method=\"dialog\">\r\n    <h2>Shortcuts</h2>\r\n    <dl class=\"help-grid\">\r\n      <div class=\"head\">Placing</div>\r\n      <dt>Drag a shape</dt><dd>Drops where you release, snapped to the grid</dd>\r\n      <dt>Click a shape</dt><dd>Drops in the middle of the sheet</dd>\r\n\r\n      <div class=\"head\">Selecting</div>\r\n      <dt><kbd>Click</kbd></dt><dd>Select one</dd>\r\n      <dt><kbd>Shift</kbd> click</dt><dd>Add to or remove from the selection</dd>\r\n      <dt>Sweep the sheet</dt><dd>Marquee select everything the box touches</dd>\r\n      <dt><kbd>Ctrl</kbd> <kbd>A</kbd></dt><dd>Select everything</dd>\r\n      <dt><kbd>Esc</kbd></dt><dd>Deselect</dd>\r\n\r\n      <div class=\"head\">Editing</div>\r\n      <dt>Drag</dt><dd>Move the whole selection</dd>\r\n      <dt>Square handle</dt><dd>Set a length and an angle together</dd>\r\n      <dt>Round grip</dt><dd>Rotate. Hold <kbd>Shift</kbd> for 15° steps</dd>\r\n      <dt>Arrow keys</dt><dd>Nudge a quarter step, <kbd>Shift</kbd> for a full step</dd>\r\n      <dt><kbd>Ctrl</kbd> <kbd>D</kbd></dt><dd>Duplicate, keeping links inside the copy</dd>\r\n      <dt><kbd>Ctrl</kbd> <kbd>C</kbd> / <kbd>V</kbd></dt><dd>Copy and paste</dd>\r\n      <dt><kbd>Del</kbd></dt><dd>Remove the selection</dd>\r\n      <dt><kbd>Ctrl</kbd> <kbd>Z</kbd></dt><dd>Undo, <kbd>Shift</kbd> to redo</dd>\r\n\r\n      <div class=\"head\">View</div>\r\n      <dt><kbd>Ctrl</kbd> wheel</dt><dd>Zoom about the pointer</dd>\r\n      <dt>Middle drag</dt><dd>Pan. <kbd>Space</kbd> and drag does the same</dd>\r\n      <dt>Right click</dt><dd>Context menu</dd>\r\n      <dt><kbd>Fit</kbd></dt><dd>Zoom so the whole sheet fits the window</dd>\r\n\r\n      <div class=\"head\">Space to draw in</div>\r\n      <dt>Sheet edge grips</dt><dd>Drag the top or right edge to enlarge the sheet</dd>\r\n      <dt>Panel dividers</dt><dd>Drag to resize, double click to collapse</dd>\r\n      <dt>Panel buttons</dt><dd>Hide either side panel from the toolbar</dd>\r\n    </dl>\r\n    <div class=\"row gap\">\r\n      <span class=\"spacer\"></span>\r\n      <button value=\"close\" class=\"primary\">Close</button>\r\n    </div>\r\n  </form>\r\n</dialog>\r\n\r\n<script type=\"module\" src=\"src/main.js?v=webmcp32\"></script>\n</body>\r\n</html>\r\n",
