    "body": "<!doctype html>\n<html><head><meta charset=\"utf-8\"><title>shape gallery</title>\n<style>\n body { font: 13px system-ui, sans-serif; background: #fff; color: #14181f; margin: 14px; }\n h2 { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #2f5fd0; margin: 18px 0 6px; }\n .grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 10px; }\n .cell { border: 1px solid #dfe3ea; border-radius: 6px; padding: 6px; text-align: center; }\n .cell svg { display: block; margin: 0 auto; background: #fff; }\n .name { font-size: 11px; color: #5f6773; margin-top: 4px; }\n</style></head><body>\n<div id=\"out\"></div>\n<script type=\"module\">\nfor (const f of ['common','annotation','geometry','mechanics','mechanics-parts','plots',\n  'plots-extra','schematic','optics','optics-parts','fields','circuit']) {\n  await import(`./src/types/${f}.js`);\n}\nconst { typesByGroup, createElement } = await import('./src/registry.js');\nconst { renderDocument } = await import('./src/render.js');\nconst { iconFor } = await import('./src/icons.js');\n\nconst out = document.getElementById('out');\n\nfor (const [group, types] of typesByGroup()) {\n  const h = document.createElement('h2');\n  h.textContent = group;\n  out.append(h);\n\n  const grid = document.createElement('div');\n  grid.className = 'grid';\n\n  for (const type of types) {\n    // Draw each shape big, on its icon framing, so the geometry is checkable.\n    const icon = iconFor(type.name);\n    const scale = Math.min(190 / icon.w, 130 / icon.h);\n    const taken = new Set();\n    const elements = icon.extra.map((e) => {\n      const x = createElement(e.type, { id: e.id, ...e.values }, taken);\n      taken.add(x.id); return x;\n    });\n    elements.push(createElement(type.name, { ...icon.values, label: '' }, taken));\n\n    const doc = { title: '', canvas: { width: icon.w, height: icon.h, grid: 1, showGrid: false, snap: false }, elements };\n    const cell = document.createElement('div');\n    cell.className = 'cell';\n    try {\n      const { root } = renderDocument(doc, { scale }, { selection: [], interactive: false, margin: 6 });\n      cell.append(root);\n    } catch (error) {\n      cell.textContent = 'FAILED: ' + error.message;\n    }\n    const name = document.createElement('div');\n    name.className = 'name';\n    name.textContent = type.label;\n    cell.append(name);\n    grid.append(cell);\n  }\n  out.append(grid);\n}\ndocument.title = 'ready';\n</script>\n</body></html>\n",
